/* ==================== المالية والخزنة ==================== */
let finTab='overview',ledgerFilter={q:'',month:'',dir:'',acct:''};
function renderFinance(){const tabs=[['overview','📊 نظرة عامة'],['ledger','📒 دفتر الخزنة'],['advances','🤝 السلف والعُهد'],['expenses','🧾 المصروفات'],['handover','🤝 تسليم وتسلم'],['closing','🔒 الإقفال والقفل'],['insight','🎯 الميزانية والتنبيهات'],['recon','🏦 مطابقة البنك'],['report','📑 التقرير الشهري والمواقف']];
  return `<div class="card tight"><div class="tabs" style="margin:0;padding:0 14px">${tabs.map(([k,l])=>`<button class="tab ${finTab===k?'active':''}" onclick="finTab='${k}';render()">${l}</button>`).join('')}</div></div>
  ${finTab==='overview'?finOverview():finTab==='ledger'?finLedger():finTab==='advances'?finAdvances():finTab==='expenses'?finExpenses():finTab==='report'?renderFinReport():finTab==='handover'?finHandover():finTab==='insight'?finInsight():finTab==='recon'?finRecon():finClosing()}`;}
function finOverview(){const bal=treasuryBalance();const mk=monthKey(today());const inM=S.treasury.filter(t=>t.direction==='in'&&t.date.startsWith(mk)).reduce((s,t)=>s+trAmt(t),0);const outM=S.treasury.filter(t=>t.direction==='out'&&t.date.startsWith(mk)).reduce((s,t)=>s+trAmt(t),0);
  const loans=S.advances.filter(a=>a.kind==='loan'&&a.status==='disbursed');const loanOut=loans.reduce((s,a)=>s+toAED(advRemaining(a),a.currency),0);const cust=S.advances.filter(a=>a.kind==='custody'&&a.status==='disbursed');const custOut=cust.reduce((s,a)=>s+toAED(advRemaining(a),a.currency),0);
  const pend=S.advances.filter(a=>a.status==='pending').length+S.expenses.filter(x=>x.status==='pending').length;const ready=S.advances.filter(a=>a.status==='approved').length;
  const byCat={};S.expenses.filter(x=>x.date.startsWith(mk)&&x.status!=='rejected').forEach(x=>{byCat[x.category]=(byCat[x.category]||0)+toAED(+x.amount,x.currency)});const cats=Object.entries(byCat).sort((a,b)=>b[1]-a[1]);setTimeout(()=>drawFinCharts(cats),0);
  const recent=[...S.treasury].sort((a,b)=>b.date.localeCompare(a.date)||b.created_at.localeCompare(a.created_at)).slice(0,8);
  const ab=accountBalances();const acctTiles=`<div class="grid g4" style="margin:16px 0 0">${Object.keys(ACCOUNTS).map(k=>`<div class="tile ${ab[k]<0?'danger':''}" onclick="ledgerFilter.acct='${k}';finTab='ledger';render()"><div class="lbl">${isBankKey(k)?'🏦':k==='cash'?'💵':'🗄️'} ${ACCOUNTS[k]}</div><div class="num" style="font-size:1.4rem">${n2(ab[k])} د.إ</div><div class="sub">اضغط لعرض حركاته</div></div>`).join('')}<div class="tile info" onclick="finTab='advances';render()"><div class="lbl">🧰 الخزينة الفرعية (مع الموظفين)</div><div class="num" style="font-size:1.4rem">${n2(S.advances.filter(a=>a.kind==='custody'&&a.status==='disbursed').reduce((s,a)=>s+toAED(advRemaining(a),a.currency),0))} د.إ</div><div class="sub">لم يتم تسويتها</div></div></div>`;
  return `${acctTiles}<div class="grid g4" style="margin:16px 0">
    <div class="tile ${bal<0?'danger':'ok'}" onclick="finTab='ledger';render()"><div class="lbl">إجمالي الخزنة (الكل)</div><div class="num" style="font-size:1.5rem">${n2(bal)} د.إ</div><div class="sub">${S.closings.length?'آخر إقفال '+fmtDate([...S.closings].sort((a,b)=>b.date.localeCompare(a.date))[0].date):'لم يُقفل بعد'}</div></div>
    <div class="tile"><div class="lbl">${typeof tr==='function'?tr('حركة'):'حركة'} ${monthName(mk)}</div><div class="num" style="font-size:1.2rem"><span style="color:var(--ok)">+${n0(inM)}</span> / <span style="color:var(--neg)">−${n0(outM)}</span></div><div class="sub">داخل / خارج بالدرهم</div></div>
    <div class="tile warn" onclick="finTab='advances';render()"><div class="lbl">سلف قائمة على الموظفين</div><div class="num" style="font-size:1.5rem">${n0(loanOut)} د.إ</div><div class="sub">${loans.length} سلفة تُسدد من الرواتب</div></div>
    <div class="tile info" onclick="finTab='advances';render()"><div class="lbl">عُهد لم يتم تسويتها</div><div class="num" style="font-size:1.5rem">${n0(custOut)} د.إ</div><div class="sub">${cust.length} عهدة مع الموظفين</div></div></div>
  <div class="grid g3" style="margin-bottom:16px">
    <div class="tile ${pend?'warn':'ok'}" onclick="finTab='advances';render()"><div class="lbl">بانتظار موافقة المدير</div><div class="num">${pend}</div><div class="sub">سلف/عُهد ومصروفات بانتظار الاعتماد</div></div>
    <div class="tile ${ready?'info':'ok'}" onclick="finTab='advances';render()"><div class="lbl">معتمدة وجاهزة للصرف</div><div class="num">${ready}</div><div class="sub">تحتاج سند صرف وتوقيع</div></div>
    <div class="tile"><div class="lbl">${typeof tr==='function'?tr('مصروفات'):'مصروفات'} ${monthName(mk).split(' ')[0]}</div><div class="num" style="font-size:1.5rem">${n0(cats.reduce((s,c)=>s+c[1],0))} د.إ</div><div class="sub">${cats.length} تصنيف</div></div></div>
  <div class="toolbar" style="margin-bottom:16px"><button class="btn primary" onclick="openExpenseForm()">＋ تسجيل مصروف</button><button class="btn" onclick="openTreasuryForm('in')">⬇️ إيداع في الخزنة</button><button class="btn" onclick="openTreasuryForm('out')">⬆️ صرف من الخزنة</button><button class="btn" onclick="printDigest()">🖨️ تقرير المدير اليومي</button></div>
  <div class="grid g2"><div class="card"><h2>🧾 مصروفات الشهر حسب التصنيف</h2><div class="chart-box"><canvas id="chExp"></canvas></div></div>
  <div class="card tight"><div class="card-head"><h2>آخر الحركات</h2><button class="btn sm" onclick="finTab='ledger';render()">الدفتر كاملاً</button></div>${recent.length?`<table><tbody>${recent.map(t=>{const e=empById(t.emp_id);return `<tr><td class="mini">${fmtDate(t.date)}</td><td>${esc(t.category)}${e?` <span class="muted mini">· ${esc(e.name)}</span>`:''}</td><td class="num" style="color:${t.direction==='in'?'var(--ok)':'var(--neg)'}">${t.direction==='in'?'+':'−'}${money(t.amount,t.currency)}</td></tr>`}).join('')}</tbody></table>`:'<div class="empty">لا توجد حركات بعد. ابدأ بضبط الرصيد الافتتاحي من الإعدادات أو بإيداع.</div>'}</div></div>`;}
function drawFinCharts(cats){mkChart('chExp',{type:'doughnut',data:{labels:cats.map(c=>c[0]),datasets:[{data:cats.map(c=>Math.round(c[1])),backgroundColor:CHART_COLORS,borderWidth:0}]},options:{responsive:true,maintainAspectRatio:false,cutout:'60%',plugins:{legend:{position:'left',labels:{boxWidth:12}}}}});}
function finLedger(){let list=[...S.treasury].filter(t=>(!ledgerFilter.month||t.date.startsWith(ledgerFilter.month))&&(!ledgerFilter.dir||t.direction===ledgerFilter.dir)&&(!ledgerFilter.q||[t.category,t.note,(empById(t.emp_id)||{}).name].join(' ').toLowerCase().includes(ledgerFilter.q.toLowerCase()))).sort((a,b)=>b.date.localeCompare(a.date)||(b.created_at||'').localeCompare(a.created_at||''));
  let run=treasuryBalance(null,ledgerFilter.acct||undefined);const rows=[];for(const t of [...S.treasury].filter(t=>!ledgerFilter.acct||acctOf(t)===ledgerFilter.acct).sort((a,b)=>b.date.localeCompare(a.date)||(b.created_at||'').localeCompare(a.created_at||''))){const bal=run;run-=t.direction==='in'?trAmt(t):-trAmt(t);if(list.includes(t))rows.push({t,bal});}
  return `<div class="card tight" style="margin-top:16px"><div class="card-head"><div class="toolbar"><input class="search" placeholder="🔍 بحث…" value="${esc(ledgerFilter.q)}" oninput="ledgerFilter.q=this.value;render()"><input type="month" class="search" style="min-width:150px" value="${ledgerFilter.month}" onchange="ledgerFilter.month=this.value;render()"><select class="search" style="min-width:120px" onchange="ledgerFilter.dir=this.value;render()"><option value="">داخل وخارج</option><option value="in" ${ledgerFilter.dir==='in'?'selected':''}>داخل فقط</option><option value="out" ${ledgerFilter.dir==='out'?'selected':''}>خارج فقط</option></select><select class="search" style="min-width:140px" onchange="ledgerFilter.acct=this.value;render()"><option value="">كل الحسابات</option>${Object.keys(ACCOUNTS).map(k=>`<option value="${k}" ${ledgerFilter.acct===k?'selected':''}>${ACCOUNTS[k]}</option>`).join('')}</select></div><div class="toolbar"><b>الرصيد: ${n2(treasuryBalance(null,ledgerFilter.acct||undefined))} د.إ</b><button class="btn" onclick="openTransferForm()">🔁 تحويل بين الحسابات</button><button class="btn" onclick="exportCSV('treasury')">⬇️ تصدير</button><button class="btn" onclick="openTreasuryForm('in')">⬇️ إيداع</button><button class="btn primary" onclick="openTreasuryForm('out')">⬆️ صرف</button></div></div>
  <div class="table-wrap">${rows.length?`<table><thead><tr><th>التاريخ</th><th>النوع</th><th>الموظف</th><th>البيان</th><th class="num">داخل</th><th class="num">خارج</th><th class="num">الرصيد بعدها</th><th>مستند</th><th></th></tr></thead><tbody>${rows.map(({t,bal})=>{const e=empById(t.emp_id);return `<tr><td>${fmtDate(t.date)}</td><td><span class="badge ${t.direction==='in'?'b-ok':'b-danger'}">${esc(t.category)}</span> <span class="badge b-muted">${ACCT_SHORT[acctOf(t)]}</span></td><td>${e?`<b data-go-emp="${e.id}" style="cursor:pointer">${esc(e.name)}</b>`:'—'}</td><td class="mini">${esc(t.note||'')}${t.ref_type?` <span class="muted">(${({advance:'سلفة',custody:'عهدة',expense:'مصروف',repayment:'سداد',custody_return:'رد عهدة',reimburse:'رد مصروف',invoice:'فاتورة',payment:'راتب',cheque:'شيك',reversal:'عكس قيد'})[t.ref_type]||esc(t.ref_type)})</span>`:''}</td><td class="num" style="color:var(--ok)">${t.direction==='in'?money(t.amount,t.currency):''}</td><td class="num" style="color:var(--neg)">${t.direction==='out'?money(t.amount,t.currency):''}</td><td class="num muted">${n2(bal)}</td><td>${t.file_id?`<button class="btn sm" onclick="viewFile('${t.file_id}')">📎</button>`:'<span class="muted mini">—</span>'}</td><td>${(!t.ref_type||refOrphan(t))?`<button class="btn sm danger" onclick="delTreasury('${t.id}')">حذف</button>`:''}</td></tr>`}).join('')}</tbody></table>`:'<div class="empty">لا توجد حركات</div>'}</div></div>`;}
function openTransferForm(){const o=Object.keys(ACCOUNTS).map(k=>`<option value="${k}">${ACCOUNTS[k]}</option>`).join('');openModal('🔁 تحويل بين الحسابات',`<div class="frow"><div class="field"><label>من حساب</label><select id="tr_from">${o}</select></div><div class="field"><label>إلى حساب</label><select id="tr_to">${o.replace('value="main"','value="main"').replace(/(value="bank")/,'$1 selected')}</select></div></div><div class="frow"><div class="field"><label>المبلغ (د.إ)</label><input type="number" step="0.01" id="tr_amt" dir="ltr"></div><div class="field"><label>التاريخ</label><input type="date" id="tr_date" value="${iso(today())}"></div></div><div class="field"><label>ملاحظة</label><input id="tr_note" placeholder="مثال: إيداع نقدي في البنك"></div><p class="muted mini">🔐 يتطلب كود المدير.</p>`,`<button class="btn primary" onclick="saveTransfer()">تحويل</button><button class="btn" onclick="closeModal()">إلغاء</button>`);}
async function saveTransfer(){return withBusy(async()=>{const a=fv('tr_from'),b=fv('tr_to'),amt=fn('tr_amt');if(a===b){toast('اختر حسابين مختلفين','err');return}if(!(amt>0)){toast('أدخل مبلغاً صحيحاً','err');return}if(!await requirePin('تحويل بين الحسابات'))return;const d=fv('tr_date')||iso(today());const note=(fv('tr_note')||'')+` (${ACCT_SHORT[a]} ← ${ACCT_SHORT[b]})`;const gid=uid();await DB.upsert('treasury',{id:uid(),date:d,direction:'out',category:'تحويل بين الحسابات',amount:amt,currency:'AED',account:a,ref_type:'transfer',ref_id:gid,note,created_by:'admin'});await DB.upsert('treasury',{id:uid(),date:d,direction:'in',category:'تحويل بين الحسابات',amount:amt,currency:'AED',account:b,ref_type:'transfer',ref_id:gid,note,created_by:'admin'});closeModal();toast('تم التحويل','ok');render();});}
function treasuryModeChange(){const c=fv('t_mode')==='custody';const h=document.getElementById('t_modeHint');if(h)h.classList.toggle('hidden',!c);const l=document.querySelector('#t_emp')&&document.querySelector('#t_emp').closest('.field')&&document.querySelector('#t_emp').closest('.field').querySelector('label');if(l)l.textContent=c?'الموظف صاحب العهدة (إلزامي)':'الموظف (اختياري)';}
function openCustodyChoice(empId){openModal('＋ عهدة جديدة',`<p class="muted">ما نوع العهدة؟</p><div class="grid g2"><div class="card" style="cursor:pointer;text-align:center;padding:18px" onclick="closeModal();openAdvanceForm('${empId}',null,'custody')"><div style="font-size:2rem">💵</div><b>عهدة نقدية (الخزينة الفرعية)</b><p class="muted mini">مبلغ نقدي يُسوّى بفواتير أو يُرد</p></div><div class="card" style="cursor:pointer;text-align:center;padding:18px" onclick="closeModal();openAssetForm('${empId}')"><div style="font-size:2rem">🧰</div><b>عهدة معدات</b><p class="muted mini">أجهزة، مفاتيح، أدوات، سيارة…</p></div></div>`,`<button class="btn" onclick="closeModal()">إلغاء</button>`);}
async function pickAnyFile(labelId){const f=await api.file.pick();if(!f)return;pendingFile=f;$('#'+labelId).textContent=f.name;}
async function saveFilePending(){if(!pendingFile)return{};const id=uid();const bin=Uint8Array.from(atob(pendingFile.data),c=>c.charCodeAt(0));await api.file.save(id,pendingFile.name,pendingFile.mime,bin.buffer);const r={file_id:id,file_name:pendingFile.name};pendingFile=null;return r;}
function refOrphan(t){const m={advance:'advances',custody:'advances',repayment:'advances',custody_return:'advances',expense:'expenses',reimburse:'expenses',invoice:'taxdocs',payment:'payments',cheque:'cheques'};const tb=m[t.ref_type];if(!tb)return true;return !S[tb].some(x=>x.id===t.ref_id);}
async function delTreasury(id){if(!await confirmDel('حذف هذه الحركة من الخزنة نهائياً؟'))return;if(!await requirePin('حذف حركة من الخزنة'))return;await DB.remove('treasury',id);render();}

/* ---- السلف والعُهد ---- */
let advFilter='open';
function finAdvances(){const list=[...S.advances].filter(a=>(!advKind||a.kind===advKind)).filter(a=>advFilter==='all'||(advFilter==='open'?['pending','approved','disbursed'].includes(a.status):a.status===advFilter)).sort((a,b)=>(b.request_date||'').localeCompare(a.request_date||''));
  return `<div class="card tight" style="margin-top:16px"><div class="card-head"><div class="toolbar">${[['open','القائمة'],['pending','بانتظار الموافقة'],['approved','جاهزة للصرف'],['disbursed','مصروفة'],['settled','مغلقة'],['rejected','مرفوضة'],['all','الكل']].map(([k,l])=>`<span class="chip ${advFilter===k?'on':''}" onclick="advFilter='${k}';render()">${l}</span>`).join('')}</div><div class="toolbar"><button class="btn" onclick="exportCSV('advances')">⬇️ تصدير</button>${advKind!=='loan'?'<button class="btn primary" onclick="openCustodyIssueForm()">＋ صرف عهدة مباشر</button>':''}<button class="btn primary" onclick="openAdvanceForm(null,null,advKind||undefined)">${advKind==='custody'?'＋ طلب عهدة (باعتماد)':advKind==='loan'?'＋ سلفة جديدة':'＋ طلب جديد'}</button></div></div>
  <div class="table-wrap">${list.length?`<table><thead><tr><th>التاريخ</th><th>الموظف</th><th>النوع</th><th class="num">المبلغ</th><th>السبب</th><th>السداد</th><th class="num">المتبقي</th><th>الحالة</th><th>سند</th><th></th></tr></thead><tbody>${list.map(a=>advRow(a)).join('')}</tbody></table>`:'<div class="empty">لا توجد طلبات</div>'}</div></div>
  <div class="card"><h3>كيف تعمل الدورة؟</h3><p class="muted mini" style="line-height:1.9">1) الأدمن يسجّل طلب السلفة/العهدة باسم الموظف وسببها → 2) المدير يعتمد بكود PIN (أو يرفض مع السبب) → 3) الأدمن يصرف: يُطبع <b>سند صرف</b> ويوقّع الموظف ورقياً ثم تُرفع صورة السند → تُخصم من الخزنة تلقائياً → 4) <b>السلفة</b> تُسدد أقساطاً من الراتب تلقائياً عند صرف كل شهر، و<b>العهدة</b> تُسوّى بمصروفات بفواتير أو برد المتبقي للخزنة. أي عهدة لم يتم تسويتها خلال ${S.settings.custodyDays} أيام تظهر تنبيهاً أحمر.</p></div>`;}
function advRow(a,inProfile){const e=empById(a.emp_id)||{name:'—'};const st=ADV_ST[a.status]||{l:a.status,cls:'b-muted'};const rem=advRemaining(a);
  const editBtn=(['pending','approved','disbursed'].includes(a.status)?`<button class="btn sm" onclick="openAdvanceForm('${a.emp_id}','${a.id}')">✏️ تعديل</button> `:'');
  const actions=editBtn+(a.status==='pending'?`<button class="btn sm ok" onclick="approveAdvance('${a.id}')">✅ اعتماد</button> <button class="btn sm danger" onclick="rejectAdvance('${a.id}')">رفض</button> <button class="btn sm" onclick="delAdvance('${a.id}')">✕</button>`:a.status==='rejected'?`<button class="btn sm" onclick="delAdvance('${a.id}')">✕ حذف</button>`:a.status==='approved'?`<button class="btn sm primary" onclick="disburseAdvance('${a.id}')">💵 صرف</button> <button class="btn sm" onclick="printVoucher('${a.id}')">🖨️ سند</button>`:a.status==='disbursed'?`${a.kind==='custody'?`<button class="btn sm" onclick="openExpenseForm('${a.emp_id}','${a.id}')">🧾 تسوية بفاتورة</button> <button class="btn sm" onclick="returnCustody('${a.id}')">↩️ رد المتبقي</button>`:`<button class="btn sm" onclick="repayAdvance('${a.id}')">💰 سداد نقدي</button>`} <button class="btn sm" onclick="printVoucher('${a.id}')">🖨️</button>`:'');
  return `<tr><td>${fmtDate(a.request_date)}${a.vno?`<div class="muted mini" dir="ltr">${esc(a.vno)}</div>`:''}</td>${inProfile?'':`<td><b data-go-emp="${a.emp_id}" style="cursor:pointer">${esc(e.name)}</b></td>`}<td><span class="badge ${a.kind==='custody'?'b-info':'b-primary'}">${a.kind==='custody'?'عهدة':'سلفة'}</span></td><td class="num"><b>${money(a.amount,a.currency)}</b></td><td class="mini">${a.section?`<span class="badge b-muted">${esc(a.section)}</span> `:''}${esc(a.reason||'')}${a.reject_reason?`<div style="color:var(--neg)">سبب الرفض: ${esc(a.reject_reason)}</div>`:''}</td><td class="mini">${a.kind==='loan'?`${a.installments} قسط × ${n2(a.installment_amount)}${a.repay_method==='cash'?' <span class="badge b-muted">نقدي</span>':' <span class="badge b-muted">من الراتب</span>'}`:'تسوية بفواتير'}</td><td class="num">${['disbursed'].includes(a.status)?money(rem,a.currency):'—'}</td><td><span class="badge ${st.cls}">${st.l}</span>${a.approved_by?`<div class="muted mini">${esc(a.approved_by)} ${fmtDate(a.approved_at)}</div>`:''}</td><td>${a.voucher_file_id?`<button class="btn sm" onclick="viewFile('${a.voucher_file_id}')">📎 موقّع</button>`:a.status==='disbursed'?`<button class="btn sm warn" style="color:var(--warn)" onclick="uploadVoucher('${a.id}')">⬆️ رفع الموقّع</button>`:'—'}</td><td>${actions}${a.kind==='custody'?` <button class="btn sm danger" onclick="deleteCustody('${a.id}')" title="حذف العهدة (بكود المدير)">🗑 حذف العهدة</button>`:''}</td></tr>`;}
function openAdvanceForm(empId,advId,presetKind){const ed=advId?S.advances.find(a=>a.id===advId):null;if(!ed&&!activeEmps().length){toast('أضف موظفاً أولاً','err');return}
  const locked=!!(ed&&['disbursed','settled'].includes(ed.status));/* بعد الصرف: تُقفل الحقول المالية (المبلغ/النوع/العملة) ويُسمح بتعديل خطة السداد والسبب */
  const empField=ed?`<input value="${esc((empById(ed.emp_id)||{}).name||'')}" disabled><input type="hidden" id="a_emp" value="${ed.emp_id}">`:`<select id="a_emp">${activeEmps().map(e=>`<option value="${e.id}" ${e.id===empId?'selected':''}>${esc(e.name)}</option>`).join('')}</select>`;
  const kindField=`<select id="a_kind" ${locked?'disabled':''} onchange="$('#a_inst_wrap').classList.toggle('hidden',this.value!=='loan');$('#a_sec_wrap').classList.toggle('hidden',this.value!=='custody')"><option value="loan" ${ed&&ed.kind==='loan'?'selected':''}>سلفة (تُسدد من الراتب)</option><option value="custody" ${(ed&&ed.kind==='custody')||(!ed&&presetKind==='custody')?'selected':''}>عهدة (تُسوّى بفواتير)</option></select>`;
  const firstDef=(ed&&ed.first_month)?ed.first_month:monthKey(new Date(today().getFullYear(),today().getMonth()+1,1));
  const showInst=ed?ed.kind==='loan':presetKind!=='custody';
  openModal(ed?'✏️ تعديل سلفة / عهدة':'طلب سلفة / عهدة',
  `${locked?'<div class="banner info" style="margin-bottom:10px"><span>هذه '+(ed.kind==='custody'?'العهدة':'السلفة')+' مصروفة — يمكنك تعديل خطة السداد والسبب فقط، أما المبلغ فمقفل.</span></div>':''}
  <div class="frow"><div class="field"><label>الموظف *</label>${empField}</div><div class="field"><label>النوع</label>${kindField}</div></div>
  <div class="frow3"><div class="field"><label>المبلغ *</label><input type="number" step="0.01" id="a_amt" dir="ltr" value="${ed?ed.amount:''}" ${locked?'readonly':''} oninput="calcInst()"></div><div class="field"><label>العملة</label><select id="a_cur" ${locked?'disabled':''}><option ${ed&&ed.currency==='AED'?'selected':''}>AED</option><option ${ed&&ed.currency==='USD'?'selected':''}>USD</option></select></div><div class="field"><label>تاريخ الطلب</label><input type="date" id="a_date" value="${ed?esc(ed.request_date||iso(today())):iso(today())}" ${locked?'readonly':''}></div></div>
  <div id="a_sec_wrap" class="${showInst?'hidden':''}"><div class="field"><label>القسم / القائمة <span class="muted mini">(اختياري)</span></label>${selWithAdd('a_section','custodySections',ed?ed.section:null)}</div>${projField('a_proj',ed?(ed.project_id||''):'','المشروع')}</div>
  <div id="a_inst_wrap" class="${showInst?'':'hidden'}"><div class="field"><label>طريقة السداد</label><select id="a_repay"><option value="salary" ${!ed||ed.repay_method!=='cash'?'selected':''}>تُخصم شهرياً من الراتب</option><option value="cash" ${ed&&ed.repay_method==='cash'?'selected':''}>سداد نقدي منفصل (لا يُخصم من الراتب)</option></select></div><div class="frow3"><div class="field"><label>عدد الأقساط</label><input type="number" min="1" max="60" id="a_inst" value="${ed?(ed.installments||1):1}" dir="ltr" oninput="calcInst('n')"></div><div class="field"><label>قيمة القسط الشهري</label><input type="number" step="0.01" id="a_inst_amt" dir="ltr" value="${ed?(ed.installment_amount||''):''}" oninput="calcInst('v')"></div><div class="field"><label>أول شهر خصم</label><input type="month" id="a_first" dir="ltr" value="${firstDef}"></div></div><p class="muted mini">اكتب عدد الأقساط ليُحسب القسط تلقائياً، أو اكتب قيمة القسط ليُحسب العدد. تظهر هذه الأقساط مجدولة في كشف حساب الموظف.</p></div>
  <div class="field"><label>السبب *</label><input id="a_reason" value="${ed?esc(ed.reason||''):''}" placeholder="مثال: ظرف عائلي / شراء خامات لموقع العميل…"></div>
  ${ed?'':'<p class="muted mini">بعد التسجيل يظهر الطلب للمدير لاعتماده بكود PIN.</p>'}`,
  `<button class="btn primary" onclick="saveAdvance('${advId||''}')">${ed?'حفظ التعديل':'تسجيل الطلب'}</button><button class="btn" onclick="closeModal()">إلغاء</button>`);}
function calcInst(from){const a=fn('a_amt');if(!(a>0)){return;}
  if(from==='v'){const v=fn('a_inst_amt');if(v>0){const n=Math.max(1,Math.min(60,Math.ceil(a/v)));$('#a_inst').value=n;}return;}
  const n=Math.max(1,fn('a_inst')||1);$('#a_inst_amt').value=(a/n).toFixed(2);}
async function saveAdvance(advId){const ed=advId?S.advances.find(a=>a.id===advId):null;const locked=!!(ed&&['disbursed','settled'].includes(ed.status));
  const amount=locked?+ed.amount:fn('a_amt');const reason=fv('a_reason');if(!(amount>0)||!reason){toast('المبلغ والسبب مطلوبان','err');return}
  const kind=locked?ed.kind:fv('a_kind');const inst=kind==='loan'?Math.max(1,fn('a_inst')||1):1;const instAmt=kind==='loan'?(fn('a_inst_amt')>0?fn('a_inst_amt'):+(amount/inst).toFixed(2)):+(amount/inst).toFixed(2);const repay=kind==='loan'?(fv('a_repay')||'salary'):'salary';const first=kind==='loan'?(fv('a_first')||null):null;
  if(ed){await DB.upsert('advances',{...ed,kind,amount,currency:locked?ed.currency:fv('a_cur'),reason,request_date:locked?ed.request_date:(fv('a_date')||ed.request_date||iso(today())),installments:inst,installment_amount:+instAmt.toFixed(2),repay_method:repay,first_month:first,section:kind==='custody'?(fv('a_section')||null):null,project_id:kind==='custody'?(fv('a_proj')||null):null,...(locked?{}:{remaining:amount})});closeModal();toast('تم حفظ تعديل السلفة ✅','ok');render();return;}
  await DB.upsert('advances',{id:uid(),emp_id:fv('a_emp'),kind,amount,currency:fv('a_cur'),reason,request_date:fv('a_date')||iso(today()),status:'pending',installments:inst,installment_amount:+instAmt.toFixed(2),repay_method:repay,first_month:first,section:kind==='custody'?(fv('a_section')||null):null,project_id:kind==='custody'?(fv('a_proj')||null):null,remaining:amount});closeModal();toast('تم تسجيل الطلب — بانتظار اعتماد المدير','ok');render();}
async function deleteCustody(id){const a=S.advances.find(x=>x.id===id);if(!a||a.kind!=='custody')return;const e=empById(a.emp_id)||{name:'—'};
  const settl=S.expenses.filter(x=>x.custody_id===id);if(settl.length){toast('لا يمكن حذف عهدة لها فواتير تسوية ('+settl.length+') — اعمل "رد المتبقي" لإغلاقها بدل الحذف','err');return}
  const rows=S.treasury.filter(t=>t.ref_id===id&&['custody','custody_return'].includes(t.ref_type));const moved=rows.some(t=>t.ref_type==='custody');
  if(!await confirmDel(`حذف العهدة (${money(a.amount,a.currency)}) للموظف ${e.name}؟${moved?` سيُلغى قيد صرفها من الخزينة ويعود المبلغ للحساب الذي خرج منه (${rows.filter(t=>t.ref_type==='custody').map(t=>ACCOUNTS[acctOf(t)]).join('، ')}).`:''} لا يمكن التراجع.`,'حذف العهدة'))return;
  if(!await requirePin('حذف عهدة '+e.name))return;
  return withBusy(async()=>{for(const t of rows)await DB.remove('treasury',t.id);await DB.remove('advances',id);toast('تم حذف العهدة'+(moved?' وإلغاء قيدها من الخزينة':''),'ok');render();});}
async function delAdvance(id){const a=S.advances.find(x=>x.id===id);if(!a||!['pending','rejected'].includes(a.status))return;if(!await confirmDel('حذف هذا الطلب؟'))return;await DB.remove('advances',id);render();}
async function approveAdvance(id){return withBusy(async()=>{const a=S.advances.find(x=>x.id===id);const e=a&&empById(a.emp_id);if(!a||a.status!=='pending'||!e){toast('الطلب غير صالح أو الموظف محذوف','err');return}if(a.kind==='loan'){const open=S.advances.filter(x=>x.emp_id===a.emp_id&&x.kind==='loan'&&x.status==='disbursed');if(open.length&&!await confirmBox(`تنبيه: ${e.name} لديه ${open.length} سلفة قائمة لم تُسدد (متبقٍ ${n2(open.reduce((s,x)=>s+toAED(advRemaining(x),x.currency),0))} د.إ). الاستمرار في الاعتماد؟`,'متابعة'))return;if(a.installment_amount>net(e)*0.5&&!await confirmBox(`القسط (${n2(a.installment_amount)}) يتجاوز نصف صافي الراتب (${n2(net(e))}). الاستمرار؟`,'متابعة'))return;}if(!await requirePin('اعتماد '+(a.kind==='custody'?'عهدة':'سلفة')+' '+e.name))return;await DB.upsert('advances',{...a,status:'approved',approved_by:'المدير',approved_at:iso(today())});await DB.upsert('notes',{id:uid(),emp_id:a.emp_id,date:iso(today()),kind:'ملاحظة',text:`اعتماد ${a.kind==='custody'?'عهدة':'سلفة'} ${money(a.amount,a.currency)} — ${a.reason}`});toast('تم الاعتماد ✅','ok');render();});}
async function rejectAdvance(id){return withBusy(async()=>{const a=S.advances.find(x=>x.id===id);if(!a||a.status!=='pending')return;const reason=await promptBox('رفض الطلب','سبب الرفض (يظهر في السجل):','text');if(reason===null)return;if(!await requirePin('رفض الطلب'))return;await DB.upsert('advances',{...a,status:'rejected',reject_reason:reason,approved_by:'المدير',approved_at:iso(today())});toast('تم الرفض');render();});}
async function disburseAdvance(id){return withBusy(async()=>{const a=S.advances.find(x=>x.id===id);const e=a&&empById(a.emp_id);if(!a||a.status!=='approved'||!e){toast('الطلب غير جاهز للصرف','err');return}const acct=await pickAccount('صرف '+(a.kind==='custody'?'العهدة':'السلفة')+' لـ '+e.name,'اختر الحساب الذي خرج منه المبلغ ('+money(a.amount,a.currency)+') — الافتراضي الخزينة الفرعية','sub');if(!acct)return;const bal=treasuryBalance(null,acct);if(toAED(a.amount,a.currency)>bal&&!await confirmBox(`رصيد (${ACCOUNTS[acct]}) ${n2(bal)} أقل من المبلغ. الاستمرار سيجعل الرصيد بالسالب. متابعة؟`,'متابعة'))return;if(!await confirmBox(`تأكيد صرف ${money(a.amount,a.currency)} من (${ACCOUNTS[acct]}) لـ ${e.name}؟ سيُخصم من الحساب ويُطبع سند الصرف للتوقيع.`,'صرف الآن'))return;if(!await requirePin('صرف '+(a.kind==='custody'?'عهدة':'سلفة')+' '+e.name))return;const d=iso(today());await DB.upsert('advances',{...a,status:'disbursed',disbursed_at:d,remaining:a.kind==='loan'?a.amount:null});await DB.upsert('treasury',{id:uid(),date:d,direction:'out',category:a.kind==='custody'?'صرف عهدة مالية':'صرف سلفة',amount:a.amount,currency:a.currency,emp_id:a.emp_id,account:acct,ref_type:a.kind==='custody'?'custody':'advance',ref_id:a.id,note:a.reason,created_by:'admin'});toast('تم الصرف وخصمه من '+ACCOUNTS[acct],'ok');render();printVoucher(id);});}
async function uploadVoucher(id){const a=S.advances.find(x=>x.id===id);const f=await api.file.pick();if(!f)return;const fid=uid();const bin=Uint8Array.from(atob(f.data),c=>c.charCodeAt(0));await api.file.save(fid,f.name,f.mime,bin.buffer);await DB.upsert('advances',{...a,voucher_file_id:fid,voucher_file_name:f.name});toast('تم حفظ السند الموقّع','ok');render();}
async function repayAdvance(id){const a=S.advances.find(x=>x.id===id);const rem=advRemaining(a);const v=await promptBox('سداد نقدي',`المتبقي ${n2(rem)}. المبلغ المسدد الآن:`,'number');if(v===null)return;const amt=Math.min(rem,+v||0);if(!(amt>0))return;const acct=await pickAccount('سداد نقدي — أودع المبلغ في أي حساب؟');if(!acct)return;await applyRepayment(a,amt,'سداد نقدي — '+ACCT_SHORT[acct],null,true,acct);toast('تم تسجيل السداد','ok');render();}
async function applyRepayment(a,amt,note,fromSalaryMonth,cash=true,acct){const newRem=Math.max(0,advRemaining(a)-amt);await DB.upsert('advances',{...a,remaining:newRem,status:newRem<=0.005?'settled':'disbursed'});if(cash)await DB.upsert('treasury',{id:uid(),date:iso(today()),direction:'in',category:'سداد سلفة',amount:amt,currency:a.currency,emp_id:a.emp_id,account:acct||'main',ref_type:'repayment',ref_id:a.id,note:note+(fromSalaryMonth?' — راتب '+monthName(fromSalaryMonth):''),created_by:'admin'});else await DB.upsert('notes',{id:uid(),emp_id:a.emp_id,date:iso(today()),kind:'ملاحظة',text:`خصم قسط سلفة ${n2(amt)} ${cur(a.currency)} من راتب ${fromSalaryMonth?monthName(fromSalaryMonth):''} (تحويل بنكي — لا يدخل الخزنة). المتبقي ${n2(newRem)}`});}
async function returnCustody(id){const a=S.advances.find(x=>x.id===id);const rem=advRemaining(a);const v=await promptBox('رد المتبقي من العهدة',`المتبقي غير المُسوّى ${n2(rem)}. المبلغ المُعاد للخزنة:`,'number');if(v===null)return;const amt=Math.min(rem,+v||0);let racct='main';if(amt>0){racct=await pickAccount('رد المتبقي من العهدة — أودعه في أي حساب؟');if(!racct)return}if(amt>0)await DB.upsert('treasury',{id:uid(),date:iso(today()),direction:'in',category:'رد عهدة مالية',amount:amt,currency:a.currency,emp_id:a.emp_id,account:racct,ref_type:'custody_return',ref_id:a.id,note:'رد متبقي عهدة',created_by:'admin'});if(advRemaining(a)<=0.005||await confirmBox('إغلاق العهدة الآن؟ (المتبقي '+n2(advRemaining(a))+')','إغلاق'))await DB.upsert('advances',{...a,status:'settled'});render();}
function printVoucher(id){const a=S.advances.find(x=>x.id===id);const e=empById(a.emp_id)||{};const isC=a.kind==='custody';api.printHTML(letterShell(`<h2 style="text-align:center;text-decoration:underline">سند صرف ${isC?'عهدة':'سلفة'} نقدية</h2><p style="text-align:left">رقم السند: ${esc(a.id.slice(-8).toUpperCase())} &nbsp; التاريخ: ${fmtDate(a.disbursed_at||iso(today()))}</p>
  <table style="width:100%;border-collapse:collapse;margin:10px 0"><tr><td><b>اسم المستلم</b></td><td>${esc(e.name||'')}</td><td><b>الرقم الوظيفي</b></td><td>${esc(e.code||'—')}</td></tr><tr><td><b>الوظيفة</b></td><td>${esc(e.job||'')}</td><td><b>الهاتف</b></td><td dir="ltr">${esc(e.phone||'')}</td></tr><tr><td><b>المبلغ</b></td><td colspan="3" style="font-size:1.2em"><b>${money(a.amount,a.currency)}</b></td></tr><tr><td><b>السبب</b></td><td colspan="3">${esc(a.reason||'')}</td></tr>${isC?`<tr><td><b>شروط العهدة</b></td><td colspan="3">تُسوّى بفواتير أصلية خلال ${S.settings.custodyDays} أيام ويُرد المتبقي للخزنة.</td></tr>`:`<tr><td><b>طريقة السداد</b></td><td colspan="3">${a.installments} قسط شهري بقيمة ${n2(a.installment_amount)} ${cur(a.currency)} تُخصم من الراتب ابتداءً من الشهر التالي.</td></tr>`}<tr><td><b>اعتماد المدير</b></td><td colspan="3">${esc(a.approved_by||'')} — ${fmtDate(a.approved_at)}</td></tr></table>
  <p>أقر أنا الموقّع أدناه باستلام المبلغ المذكور أعلاه نقداً${isC?' على سبيل العهدة وألتزم بتسويتها':' كسلفة وأوافق على خصمها من راتبي حسب الجدول المذكور'}.</p><div class="sig"><div>توقيع المستلم:<br><br>____________________</div><div>أمين الخزنة:<br><br>____________________</div><div>المدير:<br><br>____________________</div></div>`));}

/* ---- المصروفات ---- */
let expFilter={month:monthKey(today()),status:''};
function finExpenses(){const list=[...S.expenses].filter(x=>(!expFilter.month||x.date.startsWith(expFilter.month))&&(!expFilter.status||x.status===expFilter.status)).sort((a,b)=>b.date.localeCompare(a.date));const tot=list.filter(x=>x.status!=='rejected').reduce((s,x)=>s+toAED(+x.amount,x.currency),0);
  return `<div class="card tight" style="margin-top:16px"><div class="card-head"><div class="toolbar"><input type="month" class="search" style="min-width:150px" value="${expFilter.month}" onchange="expFilter.month=this.value;render()"><select class="search" style="min-width:140px" onchange="expFilter.status=this.value;render()"><option value="">كل الحالات</option><option value="pending" ${expFilter.status==='pending'?'selected':''}>بانتظار الاعتماد</option><option value="approved" ${expFilter.status==='approved'?'selected':''}>معتمدة</option><option value="rejected" ${expFilter.status==='rejected'?'selected':''}>مرفوضة</option></select><b>الإجمالي: ${n2(tot)} د.إ</b></div><div class="toolbar"><button class="btn" onclick="exportCSV('expenses')">⬇️ تصدير</button><button class="btn primary" onclick="openExpenseForm()">＋ مصروف</button></div></div>
  <div class="table-wrap">${list.length?`<table><thead><tr><th>التاريخ</th><th>من صرفه</th><th>التصنيف</th><th>البيان</th><th class="num">المبلغ</th><th>مصدر الدفع</th><th>الفاتورة</th><th>الحالة</th><th></th></tr></thead><tbody>${list.map(x=>{const e=empById(x.emp_id);const c=x.custody_id?S.advances.find(a=>a.id===x.custody_id):null;return `<tr><td>${fmtDate(x.date)}</td><td>${e?`<b data-go-emp="${e.id}" style="cursor:pointer">${esc(e.name)}</b>`:'—'}</td><td>${esc(x.category)}</td><td class="mini">${esc(x.description||'')}</td><td class="num"><b>${money(x.amount,x.currency)}</b></td><td class="mini">${c?'تسوية عهدة':x.paid_from==='treasury'?'من '+ACCOUNTS.main:x.paid_from==='cash'?'كاش':x.paid_from==='bank'?'من البنك':x.reimbursed_at?'رُدّ للموظف '+fmtDate(x.reimbursed_at):'<span class="badge b-warn">مستحق للموظف</span>'}</td><td>${x.file_id?`<button class="btn sm" onclick="viewFile('${x.file_id}')">📎</button>`:'<span class="badge b-warn">بدون فاتورة</span>'}</td><td>${x.status==='pending'?'<span class="badge b-warn">بانتظار الاعتماد</span>':x.status==='rejected'?'<span class="badge b-danger">مرفوض</span>':'<span class="badge b-ok">معتمد</span>'}</td><td>${x.status==='pending'?`<button class="btn sm ok" onclick="approveExpense('${x.id}')">✅</button> <button class="btn sm danger" onclick="rejectExpense('${x.id}')">✕</button>`:''} ${x.status==='approved'&&x.paid_from==='reimburse'&&!x.reimbursed_at?`<button class="btn sm primary" onclick="reimburseExpense('${x.id}')">💵 رد له</button>`:''} ${!x.file_id?`<button class="btn sm" onclick="attachExpenseFile('${x.id}')">⬆️ فاتورة</button>`:''}</td></tr>`}).join('')}</tbody></table>`:'<div class="empty">لا توجد مصروفات</div>'}</div></div>`;}
function openExpenseForm(empId,custodyId){pendingFile=null;const custs=S.advances.filter(a=>a.kind==='custody'&&a.status==='disbursed');openModal('تسجيل مصروف',`<div class="frow3"><div class="field"><label>التاريخ</label><input type="date" id="x_date" value="${iso(today())}"></div><div class="field"><label>المبلغ *</label><input type="number" step="0.01" id="x_amt" dir="ltr"></div><div class="field"><label>العملة</label><select id="x_cur"><option>AED</option><option>USD</option></select></div></div><div class="frow"><div class="field"><label>التصنيف</label>${selWithAdd('x_cat','expenseCategories')}</div><div class="field"><label>من صرفه</label><select id="x_emp"><option value="">الإدارة</option>${activeEmps().map(e=>`<option value="${e.id}" ${e.id===empId?'selected':''}>${esc(e.name)}</option>`).join('')}</select></div></div>${custodyId?`<div class="field"><label>تسوية عهدة</label><select id="x_src" disabled><option value="custody:${custodyId}">تسوية من العهدة لـ ${esc((empById((S.advances.find(a=>a.id===custodyId)||{}).emp_id)||{}).name||'')} (المتبقي ${n2(advRemaining(S.advances.find(a=>a.id===custodyId)||{}))})</option></select></div>`:`<div class="field"><label>مصدر الدفع (خرج من أي حساب؟)</label><select id="x_src">${Object.keys(ACCOUNTS).map(k=>`<option value="${k==='main'?'treasury':k}">${acctIcon(k)} ${esc(ACCOUNTS[k])}</option>`).join('')}</select></div>`}<div class="field"><label>طريقة الدفع</label><select id="x_method"><option value="cash">💵 كاش</option><option value="transfer">🏦 تحويل بنكي</option></select></div>${projField('x_proj',custodyId?((S.advances.find(a=>a.id===custodyId)||{}).project_id||''):'','المشروع')}<div class="field"><label>البيان *</label><input id="x_desc" placeholder="مثال: 3 أكياس أسمنت لموقع فيلا العميل…"></div><div class="field"><label>صورة الفاتورة</label><div class="toolbar"><button class="btn" onclick="pickAnyFile('x_file')">📎 اختيار</button><span id="x_file" class="muted mini">لم يتم اختيار ملف</span></div></div><p class="muted mini">المصروفات فوق ${n0(S.settings.expensePinAbove)} د.إ تحتاج اعتماد المدير قبل قيدها.</p>`,`<button class="btn primary" onclick="saveExpense()">حفظ</button><button class="btn" onclick="closeModal()">إلغاء</button>`);}
async function saveExpense(){return withBusy(async()=>{const amount=fn('x_amt'),desc=fv('x_desc');if(!(amount>0)||!desc){toast('المبلغ والبيان مطلوبان','err');if(window.shakeField)shakeField(!(amount>0)?'x_amt':'x_desc');return}const src=fv('x_src');const custody_id=src.startsWith('custody:')?src.slice(8):null;const paid_from=custody_id?'custody':src;const needPin=toAED(amount,fv('x_cur'))>(+S.settings.expensePinAbove||0);let status='approved';if(needPin){status=(await requirePin('اعتماد مصروف كبير'))?'approved':'pending';}
  const f=await saveFilePending();const x={id:uid(),date:fv('x_date')||iso(today()),emp_id:fv('x_emp')||null,category:fv('x_cat'),amount,currency:fv('x_cur'),description:desc,custody_id,status,paid_from,project_id:(document.getElementById('x_proj')?fv('x_proj'):'')||null,approved_by:status==='approved'?(needPin?'المدير':'admin'):null,...f};await DB.upsert('expenses',x);if(status==='approved'&&isAcctSrc(paid_from))await DB.upsert('treasury',{id:uid(),date:x.date,direction:'out',category:'مصروف',amount,currency:x.currency,emp_id:x.emp_id,account:paid_from==='treasury'?'main':paid_from,ref_type:'expense',ref_id:x.id,project_id:x.project_id||null,note:`${x.category}: ${desc}`,extra:JSON.stringify({'الطريقة':fv('x_method')==='transfer'?'تحويل بنكي':'كاش'}),created_by:'admin'});closeModal();toast(status==='pending'?'سُجّل المصروف بانتظار اعتماد المدير':'تم تسجيل المصروف','ok');render();});}
async function approveExpense(id){return withBusy(async()=>{const x=S.expenses.find(e=>e.id===id);if(!x||x.status!=='pending')return;if(!await requirePin('اعتماد مصروف'))return;await DB.upsert('expenses',{...x,status:'approved',approved_by:'المدير'});if(isAcctSrc(x.paid_from))await DB.upsert('treasury',{id:uid(),date:x.date,direction:'out',category:'مصروف',amount:x.amount,currency:x.currency,emp_id:x.emp_id,account:x.paid_from==='treasury'?'main':x.paid_from,ref_type:'expense',ref_id:x.id,project_id:x.project_id||null,note:`${x.category}: ${x.description}`,created_by:'admin'});toast('تم الاعتماد','ok');render();});}
async function rejectExpense(id){const x=S.expenses.find(e=>e.id===id);if(!await requirePin('رفض مصروف'))return;await DB.upsert('expenses',{...x,status:'rejected'});render();}
async function attachExpenseFile(id){const x=S.expenses.find(e=>e.id===id);const f=await api.file.pick();if(!f)return;const fid=uid();const bin=Uint8Array.from(atob(f.data),c=>c.charCodeAt(0));await api.file.save(fid,f.name,f.mime,bin.buffer);await DB.upsert('expenses',{...x,file_id:fid,file_name:f.name});render();}

/* ---- الإقفال اليومي ---- */

/* ==================== الميدان والحضور ==================== */
let fieldDate=iso(today()),fieldFilter={trade:'',status:'',q:''},fieldTab='board';
function renderField(){const tabs=[['board','📋 لوحة اليوم'],['trades','🛠️ التخصصات والجاهزية'],['perf','🏆 الأداء والمخالفات'],['history','📅 سجل الحضور']];
  return `<div class="card tight"><div class="tabs" style="margin:0;padding:0 14px">${tabs.map(([k,l])=>`<button class="tab ${fieldTab===k?'active':''}" onclick="fieldTab='${k}';render()">${l}</button>`).join('')}</div></div>${fieldTab==='board'?fieldBoard():fieldTab==='trades'?fieldTrades():fieldTab==='perf'?fieldPerf():fieldHistory()}`;}
function fieldBoard(){const emps=activeEmps().filter(e=>(!fieldFilter.trade||e.trade===fieldFilter.trade)&&(!fieldFilter.q||[e.name,e.trade,e.job].join(' ').toLowerCase().includes(fieldFilter.q.toLowerCase()))).sort((a,b)=>(a.name||'').localeCompare(b.name||'','ar'));
  const all=activeEmps();const cnt=k=>all.filter(e=>(attOf(e,fieldDate)||{}).status===k).length;const unmarked=all.filter(e=>!attOf(e,fieldDate)).length;
  const trades=[...new Set([...S.settings.trades,...all.map(e=>e.trade).filter(Boolean)])];
  return `<div class="grid g4" style="margin:16px 0">
    <div class="tile ok" onclick="fieldFilter.status='present';render()"><div class="lbl">🏢 حاضر بالمقر</div><div class="num">${cnt('present')}</div></div>
    <div class="tile" onclick="fieldFilter.status='field';render()"><div class="lbl">🚚 في الميدان / مأمورية</div><div class="num">${cnt('field')+cnt('mission')}</div><div class="sub">${[...new Set(all.map(e=>attOf(e,fieldDate)).filter(a=>a&&a.status==='field'&&a.site).map(a=>a.site))].slice(0,3).map(esc).join(' · ')}</div></div>
    <div class="tile warn" onclick="fieldFilter.status='leave';render()"><div class="lbl">🏖️ إجازة / مرضي</div><div class="num">${cnt('leave')+cnt('sick')}</div></div>
    <div class="tile ${cnt('absent')?'danger':'info'}" onclick="fieldFilter.status='absent';render()"><div class="lbl">⛔ غائب</div><div class="num">${cnt('absent')}</div><div class="sub">${unmarked} لم تُسجَّل حالتهم</div></div></div>
  <div class="card tight"><div class="card-head"><div class="toolbar"><button class="btn sm" onclick="fieldDate=iso(new Date(parseD(fieldDate).getTime()-86400000));render()">‹</button><input type="date" class="search" style="min-width:150px" value="${fieldDate}" onchange="fieldDate=this.value||iso(today());render()"><button class="btn sm" onclick="fieldDate=iso(new Date(parseD(fieldDate).getTime()+86400000));render()">›</button>${fieldDate!==iso(today())?`<button class="btn sm" onclick="fieldDate=iso(today());render()">اليوم</button>`:''}<input class="search" placeholder="🔍 اسم / تخصص" value="${esc(fieldFilter.q)}" oninput="fieldFilter.q=this.value;render()"><select class="search" style="min-width:140px" onchange="fieldFilter.trade=this.value;render()"><option value="">كل التخصصات</option>${trades.map(t=>`<option ${fieldFilter.trade===t?'selected':''}>${esc(t)}</option>`).join('')}</select>${fieldFilter.status?`<span class="chip on" onclick="fieldFilter.status='';render()">${ATT[fieldFilter.status].l} ✕</span>`:''}</div><div class="toolbar"><button class="btn" onclick="markAllPresent()">✅ الكل حاضر (غير المسجَّلين)</button><button class="btn" onclick="printDigest()">🖨️ تقرير المدير</button></div></div>
  <div class="table-wrap"><table><thead><tr><th>الموظف</th><th>التخصص</th><th>الحالة اليوم</th><th>الموقع / المهمة</th><th>تغيير سريع</th><th>الأداء (90 يوم)</th></tr></thead><tbody>${emps.filter(e=>!fieldFilter.status||(attOf(e,fieldDate)||{}).status===fieldFilter.status||(fieldFilter.status==='field'&&(attOf(e,fieldDate)||{}).status==='mission')||(fieldFilter.status==='leave'&&(attOf(e,fieldDate)||{}).status==='sick')).map(e=>{const a=attOf(e,fieldDate);const st=a?ATT[a.status]:null;const sc=scorecard(e);return `<tr><td><b data-go-emp="${e.id}" style="cursor:pointer">${esc(e.name)}</b><div class="muted mini">${esc(e.job||'')} · ${e.category==='ميداني'?'ميداني':'إداري'}${e.vehicle?' · 🚗':''}</div></td><td>${e.trade?`<span class="badge b-muted">${esc(e.trade)}</span>`:'—'}</td><td>${st?`<span class="badge ${st.cls}">${st.ic} ${st.l}</span>${a.auto?'<span class="muted mini"> (تلقائي)</span>':''}`:'<span class="badge b-muted">لم يُسجَّل</span>'}</td><td class="mini">${a&&(a.site||a.task)?`<b>${esc(a.site||'')}</b> ${esc(a.task||'')}${a.client?` <span class="muted">— ${esc(a.client)}</span>`:''}`:'—'}</td><td><div class="toolbar" style="gap:4px;flex-wrap:nowrap">${['present','field','absent'].map(k=>`<button class="btn sm ${(a||{}).status===k?(k==='absent'?'danger':'ok'):''}" onclick="setAtt('${e.id}','${k}')">${ATT[k].ic}</button>`).join('')}<button class="btn sm" onclick="openAttForm('${e.id}')">✏️</button></div></td><td><span class="badge ${sc.score>=80?'b-ok':sc.score>=60?'b-warn':'b-danger'}">${sc.score}</span> <span class="muted mini">👍${sc.good} 👎${sc.bad}</span></td></tr>`}).join('')}</tbody></table></div></div>`;}
async function setAtt(empId,status){const ex=S.attendance.find(x=>x.emp_id===empId&&x.date===fieldDate);if(status==='field'){openAttForm(empId,'field');return}await DB.upsert('attendance',{id:ex?ex.id:uid(),emp_id:empId,date:fieldDate,status,site:status==='present'?'':(ex||{}).site||'',task:status==='present'?'':(ex||{}).task||'',client:''});render();}
function openAttForm(empId,preset){const e=empById(empId);const ex=S.attendance.find(x=>x.emp_id===empId&&x.date===fieldDate)||{};const sites=[...new Set(S.attendance.map(a=>a.site).filter(Boolean))].slice(-15);openModal('حالة '+esc(e.name)+' — '+fmtDate(fieldDate),`<div class="field"><label>الحالة</label><select id="at_status">${Object.entries(ATT).map(([k,v])=>`<option value="${k}" ${(preset||ex.status||'present')===k?'selected':''}>${v.ic} ${v.l}</option>`).join('')}</select></div><div class="frow"><div class="field"><label>الموقع / العميل</label><input id="at_site" list="siteList" value="${esc(ex.site||'')}" placeholder="مثال: فيلا العميل أحمد — الشارقة"><datalist id="siteList">${sites.map(s=>`<option value="${esc(s)}">`).join('')}</datalist></div><div class="field"><label>المهمة</label><input id="at_task" value="${esc(ex.task||'')}" placeholder="تركيب تكييف / توصيل طلب #…"></div></div><div class="frow3"><div class="field"><label>اسم العميل</label><input id="at_client" value="${esc(ex.client||'')}"></div><div class="field"><label>خروج</label><input type="time" id="at_in" value="${esc(ex.check_in||'')}"></div><div class="field"><label>عودة</label><input type="time" id="at_out" value="${esc(ex.check_out||'')}"></div></div><div class="field"><label>ملاحظة</label><input id="at_note" value="${esc(ex.note||'')}"></div>`,`<button class="btn primary" onclick="saveAtt('${empId}','${ex.id||''}')">حفظ</button><button class="btn" onclick="closeModal()">إلغاء</button>`);}
async function saveAtt(empId,id){await DB.upsert('attendance',{id:id||uid(),emp_id:empId,date:fieldDate,status:fv('at_status'),site:fv('at_site'),task:fv('at_task'),client:fv('at_client'),check_in:fv('at_in'),check_out:fv('at_out'),note:fv('at_note')});closeModal();render();}
async function markAllPresent(){const list=activeEmps().filter(e=>!attOf(e,fieldDate));for(const e of list)await DB.upsert('attendance',{id:uid(),emp_id:e.id,date:fieldDate,status:'present'});toast(`تم تسجيل ${list.length} موظف كحاضر`,'ok');render();}
function fieldTrades(){const all=activeEmps();const trades=[...new Set([...S.settings.trades,...all.map(e=>e.trade).filter(Boolean)])];const rows=trades.map(t=>{const es=all.filter(e=>e.trade===t);const avail=es.filter(e=>{const a=attOf(e,iso(today()));return a&&a.status==='present'});const field=es.filter(e=>{const a=attOf(e,iso(today()));return a&&(a.status==='field'||a.status==='mission')});const off=es.filter(e=>{const a=attOf(e,iso(today()));return a&&['leave','sick','absent'].includes(a.status)});return{t,es,avail,field,off}}).filter(r=>r.es.length);
  return `<div class="card" style="margin-top:16px"><h2>🛠️ جاهزية الفرق اليوم</h2><p class="muted mini">كم فني متاح الآن من كل تخصص لاستلام مهمة جديدة.</p><div class="grid g3">${rows.map(r=>`<div class="card trade-card" style="margin:0;cursor:pointer" data-trade="${esc(r.t)}"><h3>${esc(r.t)} <span class="muted mini">(${r.es.length})</span></h3><div class="toolbar"><span class="badge b-ok">متاح ${r.avail.length}</span><span class="badge b-primary">بالميدان ${r.field.length}</span><span class="badge b-warn">غير متاح ${r.off.length}</span></div><div class="mini muted" style="margin-top:6px">${r.avail.slice(0,4).map(e=>esc(e.name)).join('، ')||'لا أحد متاح الآن'}</div></div>`).join('')||'<div class="empty">حدد تخصص كل موظف من نافذة التعديل (حقل التخصص)</div>'}</div></div>`;}
function afterRenderHooks(){document.querySelectorAll('.trade-card').forEach(el=>el.onclick=()=>{fieldTab='board';fieldFilter.trade=el.dataset.trade;render()});document.querySelectorAll('.cdoc-chip').forEach(el=>el.onclick=()=>openCompanyDocForm(null,el.dataset.type));}
function fieldPerf(){const rows=activeEmps().map(e=>({e,s:scorecard(e)})).sort((a,b)=>b.s.score-a.s.score);
  return `<div class="grid g2" style="margin-top:16px"><div class="card tight"><div class="card-head"><h2>🏆 ترتيب الأداء (آخر 90 يوم)</h2><button class="btn sm" onclick="exportCSV('performance')">⬇️ تصدير</button></div><table><thead><tr><th>#</th><th>الموظف</th><th class="num">الدرجة</th><th class="num">إنجازات</th><th class="num">مخالفات</th><th class="num">غياب</th><th class="num">أيام ميدان</th></tr></thead><tbody>${rows.map(({e,s},i)=>`<tr><td>${i+1}</td><td><b data-go-emp="${e.id}" style="cursor:pointer">${esc(e.name)}</b><div class="muted mini">${esc(e.trade||e.job||'')}</div></td><td class="num"><span class="badge ${s.score>=80?'b-ok':s.score>=60?'b-warn':'b-danger'}">${s.score}</span></td><td class="num">${s.good}</td><td class="num">${s.bad}</td><td class="num">${s.absent}</td><td class="num">${s.fieldDays}</td></tr>`).join('')}</tbody></table></div>
  <div><div class="card"><h2>✍️ تسجيل إنجاز / مخالفة</h2><div class="field"><label>الموظف</label><select id="pf_emp">${activeEmps().map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')}</select></div><div class="frow"><div class="field"><label>النوع</label><select id="pf_kind"><optgroup label="إيجابي"><option>إنجاز</option><option>شكر عميل</option><option>تقييم إيجابي</option></optgroup><optgroup label="سلبي"><option>مخالفة</option><option>شكوى عميل</option><option>تأخير</option><option>إنذار</option><option>غياب بدون إذن</option></optgroup></select></div><div class="field"><label>التاريخ</label><input type="date" id="pf_date" value="${iso(today())}"></div></div><div class="field"><label>التفاصيل</label><input id="pf_text" placeholder="مثال: أنهى تركيب 3 وحدات تكييف قبل الموعد / تأخر ساعتين عن موقع العميل"></div><button class="btn primary" onclick="savePerf()">تسجيل</button></div>
  <div class="card"><h3>كيف تُحسب الدرجة؟</h3><p class="muted mini" style="line-height:1.8">تبدأ من 70 · كل إنجاز +6 · كل مخالفة −10 · كل يوم غياب −5 · أيام الميدان حتى +15. الدرجة أداة استرشادية للمدير لمقارنة العمال وتحديد المكافآت والإنذارات.</p></div></div></div>`;}
async function savePerf(){const text=fv('pf_text');if(!text){toast('اكتب التفاصيل','err');return}await DB.upsert('notes',{id:uid(),emp_id:fv('pf_emp'),date:fv('pf_date')||iso(today()),kind:fv('pf_kind'),text});toast('تم التسجيل','ok');render();}
function fieldHistory(){const days=[];for(let i=13;i>=0;i--)days.push(iso(new Date(today().getTime()-i*86400000)));const emps=activeEmps().sort((a,b)=>(a.name||'').localeCompare(b.name||'','ar'));const col={present:'#2FD1C0',field:'#12B5A6',mission:'#7C80F0',leave:'#F2A93C',sick:'#F2A93C',absent:'#E25555',off:'#4C6470'};
  return `<div class="card tight" style="margin-top:16px"><div class="card-head"><h2>📅 آخر 14 يوم</h2><div class="toolbar mini">${Object.entries(ATT).map(([k,v])=>`<span><span class="dot" style="background:${col[k]}"></span>${v.l}</span>`).join('')}<button class="btn sm" onclick="exportCSV('attendance')">⬇️ تصدير</button></div></div><div class="table-wrap"><table><thead><tr><th>الموظف</th>${days.map(d=>`<th style="text-align:center">${d.slice(8)}</th>`).join('')}<th class="num">غياب</th><th class="num">ميدان</th></tr></thead><tbody>${emps.map(e=>{const as=days.map(d=>attOf(e,d));return `<tr><td><b data-go-emp="${e.id}" style="cursor:pointer">${esc(e.name)}</b></td>${as.map((a,i)=>`<td style="text-align:center" title="${a?ATT[a.status].l+(a.site?' — '+esc(a.site):''):'لم يُسجَّل'}"><span class="dot" style="background:${a?col[a.status]:'rgba(255,255,255,.12)'};margin:0;cursor:pointer" onclick="fieldDate='${days[i]}';fieldTab='board';render()"></span></td>`).join('')}<td class="num">${as.filter(a=>a&&a.status==='absent').length}</td><td class="num">${as.filter(a=>a&&(a.status==='field'||a.status==='mission')).length}</td></tr>`}).join('')}</tbody></table></div></div>`;}

/* ==================== تقرير المدير اليومي ==================== */
function printDigest(){const t=iso(today());const all=activeEmps();const by=k=>all.filter(e=>(attOf(e,t)||{}).status===k);const alerts=computeAlerts();const bal=treasuryBalance();const mk=monthKey(t);const outM=S.treasury.filter(x=>x.direction==='out'&&x.date.startsWith(mk)).reduce((s,x)=>s+trAmt(x),0);const inM=S.treasury.filter(x=>x.direction==='in'&&x.date.startsWith(mk)).reduce((s,x)=>s+trAmt(x),0);
  const sec=(title,rows)=>`<h3 style="margin:16px 0 6px;border-bottom:1px solid #ccc">${title}</h3>${rows.length?`<ul style="margin:0;padding-inline-start:18px">${rows.map(r=>`<li>${r}</li>`).join('')}</ul>`:'<p style="color:#666;margin:0">— لا شيء</p>'}`;
  api.printHTML(letterShell(`<h2 style="text-align:center">تقرير المدير اليومي — ${fmtDate(t)}</h2>
  <table style="width:100%;border-collapse:collapse;text-align:center"><tr style="background:#eee"><th>حاضر بالمقر</th><th>في الميدان</th><th>إجازة/مرضي</th><th>غائب</th><th>رصيد الخزنة</th><th>حركة الشهر</th></tr><tr><td>${by('present').length}</td><td>${by('field').length+by('mission').length}</td><td>${by('leave').length+by('sick').length}</td><td style="color:#c00"><b>${by('absent').length}</b></td><td><b>${n2(bal)} د.إ</b></td><td>+${n0(inM)} / −${n0(outM)}</td></tr></table>
  ${sec('🚚 في الميدان الآن',[...by('field'),...by('mission')].map(e=>{const a=attOf(e,t);return `<b>${esc(e.name)}</b> (${esc(e.trade||e.job||'')}) — ${esc(a.site||'')} ${esc(a.task||'')}${a.client?' — '+esc(a.client):''}`}))}
  ${sec('⛔ غائبون اليوم',by('absent').map(e=>esc(e.name)))}
  ${sec('🔴 تنبيهات عاجلة',alerts.filter(a=>a.lvl<=1).map(a=>esc(a.txt)))}
  ${sec('🤝 طلبات تنتظر قرارك',[...S.advances.filter(a=>a.status==='pending').map(a=>`${a.kind==='custody'?'عهدة':'سلفة'} ${money(a.amount,a.currency)} — ${esc((empById(a.emp_id)||{}).name||'')} — ${esc(a.reason)}`),...S.expenses.filter(x=>x.status==='pending').map(x=>`مصروف ${money(x.amount,x.currency)} — ${esc(x.category)} — ${esc(x.description)}`)])}
  ${sec('💵 حركات الخزنة اليوم',S.treasury.filter(x=>x.date===t).map(x=>`${x.direction==='in'?'⬇️':'⬆️'} ${esc(x.category)} ${money(x.amount,x.currency)}${x.emp_id?' — '+esc((empById(x.emp_id)||{}).name||''):''} ${esc(x.note||'')}`))}
  ${sec('📝 إنجازات ومخالفات آخر 7 أيام',S.notes.filter(n=>n.date>=iso(new Date(today().getTime()-7*86400000))&&['إنجاز','شكر عميل','مخالفة','شكوى عميل','تأخير','إنذار','غياب بدون إذن'].includes(n.kind)).map(n=>`${['إنجاز','شكر عميل'].includes(n.kind)?'👍':'👎'} <b>${esc((empById(n.emp_id)||{}).name||'')}</b>: ${esc(n.kind)} — ${esc(n.text)}`))}
  <p class="mini" style="margin-top:20px;color:#666">تقرير تلقائي من منصة شؤون الموظفين — ${new Date().toLocaleString(LOCALE())}</p>`));}
